async function creditForm(d){const detail=await api('documento?id='+d.id);let reason;await quantityForm('Nota de crédito de '+d.folio,(detail.pendientesAcreditar||d.partidas.map((l,i)=>({...l,linea:i,pendienteAcreditar:l.cantidad}))).map(l=>({...l,pending:l.pendienteAcreditar,extra:{linea:l.linea}})),async(partidas,clave)=>api('nota-credito',{factura:d.id,partidas,motivo:reason.value,clave}),b=>{reason=field(b,'Motivo del ajuste comercial','textarea');reason.required=true;note(b,'La nota ajusta el saldo del cliente. La devolución física se registra aparte desde la remisión. Su CFDI de egreso queda pendiente del PAC.')})}
