async function paymentForm(d){const detail=await api('documento?id='+d.id);let amount,kind,date,method,reference;const key=newKey(),b=modal('Registrar cobro / reembolso · '+d.folio,async()=>api('pago',{factura:d.id,revisionCuenta:detail.revisionCuenta,tipo:kind.value,importe:amount.value,fecha:date.value,metodo:method.value,referencia:reference.value,clave:key}));note(b,'Saldo actual: '+detail.saldo+' '+(d.moneda||'MXN')+'. Este registro no realiza una transferencia bancaria.');const g=grid(b);kind=field(g,'Movimiento','select',Number(detail.saldo)<0?'REEMBOLSO':'ABONO',[['ABONO','Cobro recibido'],['REEMBOLSO','Reembolso al cliente']]);amount=field(g,'Importe','number','');amount.required=true;date=field(g,'Fecha del movimiento','date',new Date().toLocaleDateString('en-CA'));date.required=true;method=field(g,'Forma de registro','select','TRANSFERENCIA',[['TRANSFERENCIA','Transferencia'],['EFECTIVO','Efectivo'],['TARJETA','Tarjeta'],['CHEQUE','Cheque'],['OTRO','Otro']]);reference=field(g,'Referencia / comprobante');reference.required=true;note(b,'El recibo interno se descarga desde Consultar factura. Los complementos fiscales de pago quedan pendientes del PAC.')}
async function cancelPayment(d,p){const snapshot=await api('documento?id='+d.id);let reason;const operationKey=newKey();const b=modal('Cancelar registro '+p.folio,async()=>api('cancelar-pago',{factura:d.id,pago:p.id,revisionCuenta:snapshot.revisionCuenta,motivo:reason.value,clave:operationKey}));reason=field(b,'Motivo de cancelación','textarea');reason.required=true;note(b,'Se conserva el registro del pago y su motivo. No se envía una orden bancaria.')}
async function cancelCommercial(d){let reason;const key=newKey(),b=modal('Cancelar '+d.folio,async()=>api('cancelar',{id:d.id,revision:d.revision,motivo:reason.value,clave:key}));reason=field(b,'Motivo de cancelación','textarea');reason.required=true;note(b,'Primero deben resolverse los documentos dependientes. Los movimientos físicos se revierten con entradas/salidas auditadas y no pueden dejar existencias negativas.')}
async function reports(){
 const content=$('content'),f=grid(content),from=field(f,'Desde','date',''),to=field(f,'Hasta','date',''),product=field(f,'Producto / SKU',production?'select':'text','',production?[['','Todos'],...meta.materiales.map(m=>[m.sku,m.sku+' '+m.nombre])]:undefined),warehouse=field(f,'Almacén','select','',[['','Todos'],...warehouseOptions()]),branch=field(f,'Sucursal','select','',[['','Todas'],...[...new Set(meta.almacenes.filter(w=>!production||w.empresa===company).map(w=>w.sucursal))].map(v=>[v,v])]);
 let type,status,client,pedido,docState,shipping,pending;
 if(!production){
  type=field(f,'Tipo de documento','select','FACTURA',[['','Todos'],...Object.entries(kindNames)]);
  status=field(f,'Estado de cobro','select','',[['','Todos'],['PENDIENTE','Pendiente'],['PARCIAL','Parcial'],['VENCIDA','Vencida'],['PAGADA','Pagada'],['A_FAVOR','Saldo a favor']]);
  docState=field(f,'Estado del documento','select','',[['','Todos'],['PRESUPUESTO','Presupuesto pendiente'],['ACEPTADO','Presupuesto aceptado'],['RECHAZADO','Presupuesto rechazado'],['CANCELADO','Cancelado'],['EMITIDA','Emitido'],['PENDIENTE_PAC','Pendiente de PAC']]);
  shipping=field(f,'Estado del surtido','select','',[['','Todos'],['CONFIRMADO','Confirmado, sin surtir'],['PARCIALMENTE_SURTIDO','Surtido parcial'],['SURTIDO_COMPLETO','Surtido completo']]);pending=field(f,'Sólo pendientes de facturar','checkbox',false);
  client=field(f,'Cliente','select','',[['','Todos los autorizados'],...(meta.clientes||[]).map(c=>[c.id,c.nombre])]);
 }else{status=field(f,'Estado','select','',[['','Todos'],...Object.entries(stateNames)]);pedido=field(f,'Pedido relacionado (folio o ID)','text','');}
 const view=field(f,'Contenido del reporte','select',production?'ORDENES':'DOCUMENTOS',production?[['ORDENES','Órdenes y costos'],['MOVIMIENTOS','Movimientos de producción'],['CONSUMOS','Consumo real de materiales'],['MERMAS','Mermas y pérdidas'],['LOTES','Fabricación por lote'],['CALIDAD','Dictámenes de calidad']]:[['DOCUMENTOS','Documentos comerciales'],['PAGOS','Cobros y reembolsos']]);
 const columnBox=node('details',content);let columns=[];
 function columnsForView(){
  columnBox.replaceChildren();node('summary',columnBox,'Columnas del reporte');let choices;
  if(production&&view.value==='ORDENES')choices={folio:'Folio',estado:'Estado',sucursal:'Sucursal',producto:'Producto',unidad:'Unidad',cantidadPlaneada:'Planeado',cantidadFabricada:'Fabricado',cantidadRechazada:'Rechazado',cantidadRecibida:'Recibido',cantidadPendiente:'Pendiente',inicio:'Inicio',fin:'Fin',responsable:'Responsable',pedido:'Pedido',...(can('costos')?{costoEstimado:'Estimado',costoReal:'Real',variacion:'Variación',costoUnitario:'Costo unitario',costoRedondeo:'Redondeo'}:{})};
  else if(production)choices={folio:'Orden',fecha:'Fecha',evento:'Evento',sucursal:'Sucursal',producto:'Producto',almacen:'Almacén',sku:'SKU',cantidad:'Cantidad',unidad:'Unidad',lote:'Lote',caducidad:'Caducidad',estado:'Estado / Dictamen',observaciones:'Observaciones',actor:'Responsable',...(can('costos')?{costoUnitario:'Costo unitario',importe:'Importe'}:{})};
  else if(view.value==='PAGOS')choices={folio:'Recibo',factura:'Factura',cliente:'Cliente',fecha:'Fecha',tipo:'Movimiento',importe:'Importe',moneda:'Moneda',metodo:'Método',referencia:'Referencia',estado:'Estado'};
  else choices={folio:'Folio',tipo:'Documento',fecha:'Fecha',cliente:'Cliente',sucursal:'Sucursal',sku:'SKU',cantidad:'Cantidad',estado:'Estado',base:'Subtotal',impuesto:'Impuestos',total:'Total',saldo:'Saldo factura',surtidoEstado:'Estado de surtido'};
  columns=Object.entries(choices).map(([id,label])=>[id,field(columnBox,label,'checkbox',true)]);
 }
 view.onchange=columnsForView;columnsForView();const result=node('div',content);
 function query(){return new URLSearchParams({empresa:company,desde:from.value,hasta:to.value,producto:product.value,almacen:warehouse.value,sucursal:branch.value,estado:production?status.value:docState.value,estadoCobro:production?'':status.value,surtidoEstado:shipping?.value||'',pendienteFacturar:pending?.checked?'1':'',tipo:type?.value||'',cliente:client?.value||'',pedido:pedido?.value||'',vista:view.value,columnas:columns.filter(([k,i])=>i.checked).map(([k])=>k).join(',')})}
 const actions=node('div',content);actions.className='bar';
 for(const ext of ['xlsx','csv','pdf'])button(actions,'Descargar '+ext.toUpperCase(),()=>download('reportes/'+ext+'?'+query(),(production?'Produccion':'Ciclo_comercial')+'.'+ext));
 button(actions,'Consultar',async()=>{result.replaceChildren();if(production&&view.value!=='ORDENES'||!production&&view.value==='PAGOS'){note(result,'Descarga el detalle en Excel, CSV o PDF con los filtros y columnas seleccionados.');return}
  if(production){const rows=(await api('ordenes?'+query())).ordenes;table(result,['Folio','Estado','Producto','Planeado','Recibido','Pendiente',...(can('costos')?['Estimado','Real','Unitario']:[])],rows.map(o=>[o.folio,o.estado,o.producto,o.cantidadPlaneada,o.cantidadRecibida,o.cantidadPendiente,...(can('costos')?[o.costoEstimado,o.costoReal,o.costoUnitario]:[])]))}
  else{const rows=(await api('documentos?'+query())).documentos;table(result,['Folio','Documento','Cliente','Estado','Total','Saldo'],rows.map(d=>[d.folio,d.tipo,d.cliente?.nombre||d.clienteOpcional,d.estadoCobro||d.surtidoEstado||d.estado,d.total,d.saldo||'']))}
 });
}

await run(async()=>{await bootstrap();const q=new URLSearchParams(location.search);if(production&&q.get('pedido')&&q.get('receta'))await productionCreate({pedido:q.get('pedido'),pedidoFolio:q.get('folio'),receta:q.get('receta'),cantidad:q.get('cantidad'),seleccion:q.get('seleccion')||'FALTANTE'})});
